- (BOOL)canBecomeFocused
{
  if ([self isTVFocusGuide]) {
    return NO;
  }
  return _props->isTVSelectable;
}

#if TARGET_OS_TV
// Portico: a plain view that cannot take focus itself and either draws no background (an empty, full-screen pass-through
// layer, such as the app's playback host over its pages) or takes no input (pointerEvents none: a dim or a scrim) is
// transparent to the focus engine, so the items under it can still be reached. Without this tvOS treats them as covered and
// offers no move to them at all.
- (BOOL)isTransparentFocusItem
{
  return [self class] == [RCTViewComponentView class] && ![self canBecomeFocused] &&
      (_props->pointerEvents == PointerEventsMode::None || _backgroundColor == nil || CGColorGetAlpha(_backgroundColor.CGColor) == 0);
}
#endif

// Portico: a nextFocus guide sits this far outside its item. Glued to the item's edge it lay inside an item that grows when
// focused (and was further off inside scroll views), so the focus engine never used it.
static const CGFloat kPorticoFocusGuideGap = 40.0;

- (void)enableDirectionalFocusGuides
{
  if (!self.isFocused) {
    return;
  }
  // Portico: resolve the targets each time this item takes focus. They were looked up once, when the prop changed, which for
  // a new view is before it is in the window, so the target stayed nil.
  UIView *porticoRoot = [self containingRootView];
  if (porticoRoot != nil) {
    if (_props->nextFocusUp.has_value()) self->_nextFocusUp = [porticoRoot viewWithTag:_props->nextFocusUp.value()];
    if (_props->nextFocusDown.has_value()) self->_nextFocusDown = [porticoRoot viewWithTag:_props->nextFocusDown.value()];
    if (_props->nextFocusLeft.has_value()) self->_nextFocusLeft = [porticoRoot viewWithTag:_props->nextFocusLeft.value()];
    if (_props->nextFocusRight.has_value()) self->_nextFocusRight = [porticoRoot viewWithTag:_props->nextFocusRight.value()];
  }
